package com.bank.pipeline;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class PipelineSecurityAuditor {
    private static final Logger log = Logger.getLogger(PipelineSecurityAuditor.class.getName());

    public static void main(String[] args) {
        log.info("Bank: National Bank of India — CI/CD pipeline security auditor");

        // The CURRENT (weak) pipeline config under audit.
        PipelineConfig config = new PipelineConfig();
        config.setUsesOidc(false);                 // DANGER: long-lived cloud key
        config.setUsesEphemeralRunners(true);
        config.setPinsActionShas(false);           // DANGER: mutable tags
        config.setLeastPrivilegeDeployRole(true);
        config.setUsesInternalRegistry(true);
        config.setPinsDependencyChecksums(false);  // DANGER: no checksum verification
        config.setSignsArtifacts(true);

        // Map config to controls with severities.
        List<SecurityControl> controls = List.of(
            new SecurityControl("OIDC federation (no long-lived keys)", config.usesOidc(), "CRITICAL"),
            new SecurityControl("Ephemeral runners", config.usesEphemeralRunners(), "HIGH"),
            new SecurityControl("Pinned action SHAs", config.pinsActionShas(), "HIGH"),
            new SecurityControl("Least-privilege deploy role", config.leastPrivilegeDeployRole(), "CRITICAL"),
            new SecurityControl("Internal registry / CodeArtifact", config.usesInternalRegistry(), "HIGH"),
            new SecurityControl("Pinned dependency checksums", config.pinsDependencyChecksums(), "HIGH"),
            new SecurityControl("Artifact signing + provenance", config.signsArtifacts(), "HIGH")
        );

        List<String> criticalGaps = new ArrayList<>();
        for (SecurityControl c : controls) {
            if (c.satisfied()) {
                log.info(() -> "PASS: " + c.name());
            } else {
                log.severe(() -> "GAP [" + c.severity() + "]: " + c.name() + " is NOT satisfied");
                if (c.severity().equals("CRITICAL")) criticalGaps.add(c.name());
            }
        }

        if (!criticalGaps.isEmpty()) {
            log.severe(() -> "AUDIT FAILED: critical gaps must be fixed before deploy → " + criticalGaps);
        } else {
            log.info("AUDIT PASSED: no critical gaps");
        }
    }
}

