package com.bank.pipeline;

class SecurityControl {
    private final String name;
    private final boolean satisfied;
    private final String severity; // CRITICAL or HIGH

    SecurityControl(String name, boolean satisfied, String severity) {
        this.name = name;
        this.satisfied = satisfied;
        this.severity = severity;
    }
    String name() { return name; }
    boolean satisfied() { return satisfied; }
    String severity() { return severity; }
}
